-- Généré par scripts/import_lot2.py — mini-jeux du lot 2 (M01, M04, M11, M12, M07). Ne pas modifier à la main.
with src as (select * from jsonb_to_recordset($n$[{"config": {"code": "M01", "engine": "board", "mechanic": "tic_tac_toe", "parameters": {"columns": 3, "default_series_wins": 1, "rows": 3, "series_wins": [1, 2, 3], "turn_timer": null}, "rounds": 12, "score": "duel", "settings": {"series_wins": {"default": 1, "label": "Victoires pour gagner la série", "options": [1, 2, 3]}}, "turn": "alternate", "version": "noodeu-c34-1.0.0"}, "id": "N2-076", "rules": {"details": ["Score : 1 victoire par manche gagnée ; 0 pour une nulle.", "Adaptation Noodeu : Tirage initial serveur, alternance des revanches et série plafonnée.", "Source de mécanique : Noughts and Crosses — NRICH / University of Cambridge (https://nrich.maths.org/games/noughts-and-crosses).", "Règles rédigées par Noodeu (règles originales Noodeu, sources séparées)."], "how_to": ["Le premier joueur est tiré au sort : il joue X, l'autre O. À chaque nouvelle manche de la série, le premier joueur alterne.", "Chacun son tour, pose ton symbole dans une case vide.", "Trois symboles alignés (ligne, colonne ou diagonale) gagnent aussitôt, même sur la neuvième case. Plateau plein sans alignement : manche nulle.", "Une manche gagnée vaut 1 victoire. La série se joue en 1, 2 ou 3 victoires (réglage du salon), 12 manches au plus ; égalité possible."], "objective": "Alignez trois symboles sur un plateau de neuf cases.", "privacy": "Le plateau est visible par vous deux ; le serveur vérifie chaque coup.", "step_texts": {}}}, {"config": {"code": "M04", "engine": "board", "mechanic": "dots_boxes", "parameters": {"boxes": 16, "dot_columns": 5, "dot_rows": 5, "edges": 40, "turn_timer": null}, "rounds": 1, "score": "duel", "turn": "alternate", "version": "noodeu-c34-1.0.0"}, "id": "N2-079", "rules": {"details": ["Score : 1 point par carré, maximum total 16.", "Adaptation Noodeu : Taille mobile 5 × 5 points.", "Source de mécanique : Put Yourself in a Box — NRICH / University of Cambridge (https://nrich.maths.org/games/put-yourself-box).", "Règles rédigées par Noodeu (règles originales Noodeu, sources séparées)."], "how_to": ["Le premier joueur est tiré au sort. Chacun son tour, trace un trait entre deux points voisins, à l'horizontale ou à la verticale.", "Fermer le quatrième côté d'une case te la donne : 1 point par case, 2 si ton trait en ferme deux.", "Tant que tu fermes au moins une case, tu rejoues ; sinon la main passe.", "Quand les 16 cases sont fermées, le plus de cases l'emporte ; 8 à 8, c'est une égalité."], "objective": "Fermez des carrés et gardez la main tant que vous en complétez.", "privacy": "Le plateau est visible par vous deux ; le serveur attribue les carrés.", "step_texts": {}}}, {"config": {"code": "M11", "engine": "board", "mechanic": "rps", "parameters": {"choice_timeout_seconds": 30, "max_total_engagements": 20, "wins_target": 2}, "rounds": 20, "score": "duel", "turn": "simultaneous", "version": "noodeu-c34-1.0.0"}, "id": "N2-083", "rules": {"details": ["Score : Premier à 2 victoires décisives ; égalités 0.", "Adaptation Noodeu : Choix sur écran plutôt que geste physique.", "Adaptation Noodeu : Attente de 30 s et série plafonnée.", "Source de mécanique : Official Rules v1.0 — IFRPS (site signalé prototype) (https://ifrps.org/rules).", "Règles rédigées par Noodeu (règles originales Noodeu, sources séparées)."], "how_to": ["Chacun choisit en secret pierre, feuille ou ciseaux, puis verrouille son choix : il ne peut plus changer.", "Les deux gestes sont révélés ensemble. Pierre bat ciseaux, ciseaux bat feuille, feuille bat pierre ; même geste : égalité, 0 point.", "Chaque manche dure 30 secondes. Si un choix manque, la manche est annulée sans montrer le geste de l'autre et sans point.", "Le premier à 2 manches gagnées remporte la partie. Après 20 manches, la série s'arrête sur le score du moment."], "objective": "Trois gestes, un choix secret et une révélation commune.", "privacy": "Ton geste reste secret jusqu'à la révélation commune ; un geste isolé n'est jamais montré.", "step_texts": {}}}, {"config": {"code": "M12", "engine": "board", "mechanic": "nd_pig", "parameters": {"dice": 1, "target": 100, "turn_timer": null, "win_requires_hold": true}, "rounds": 1, "score": "duel", "turn": "alternate", "version": "noodeu-c34-1.0.0"}, "id": "nd-de-chanceux", "rules": {"details": ["Score : Score conservé ; premier à au moins 100 après S’arrêter.", "Adaptation Noodeu : Un seul dé ; aucune règle double 1.", "Adaptation Noodeu : Victoire après conservation explicite.", "Source de mécanique : Pig dice game — NSW Department of Education (https://education.nsw.gov.au/teaching-and-learning/curriculum/mathematics/everyday-maths/primary/resources/pig-dice-game).", "Source de mécanique : Optimal Play of the Dice Game Pig — Todd W. Neller et Clifton G. M. Presser / COMAP, 2004 (https://cs.gettysburg.edu/~tneller/papers/pig.pdf).", "Règles rédigées par Noodeu (règles originales Noodeu, sources séparées)."], "how_to": ["Le premier joueur est tiré au sort. À ton tour, lance le dé autant de fois que tu veux : chaque résultat de 2 à 6 s'ajoute au total du tour.", "Un 1 fait perdre le total du tour et passe la main ; les points déjà conservés restent acquis.", "S'arrêter ajoute le total du tour à ton score conservé et passe la main.", "Le premier qui atteint 100 points conservés en s'arrêtant gagne, sans dernier tour pour l'autre. Le dé est lancé par le serveur."], "objective": "Relancez pour cumuler, ou conservez vos points avant de tomber sur un 1.", "privacy": "Le dé est lancé par le serveur ; vous voyez tous les deux chaque lancer.", "step_texts": {}}}, {"config": {"code": "M07", "engine": "board", "mechanic": "battleship", "parameters": {"adjacency": "allowed", "columns": 10, "fleet": [5, 4, 3, 3, 2], "hit_extra_turn": false, "rows": 10, "salvo": false, "shots_per_turn": 1}, "rounds": 1, "score": "duel", "turn": "alternate", "version": "noodeu-c34-1.0.0"}, "id": "N2-078", "rules": {"details": ["Score : Navires coulés et victoire ; aucun point relationnel.", "Adaptation Noodeu : Voisinage autorisé explicité.", "Adaptation Noodeu : Art et navires originaux Noodeu.", "Source de mécanique : Battleship F4527, notice française — Hasbro (https://instructions.hasbro.com/api/download/F4527_fr-fr_battleship-jeu-de-strategie-pour-enfants-a-partir-de-7-ans-pour-2-joueurs.pdf).", "Règles rédigées par Noodeu (règles originales Noodeu, sources séparées)."], "how_to": ["Grille de A à J et de 1 à 10, cinq navires de 5, 4, 3, 3 et 2 cases. Place-les droits, sans chevauchement ; ils peuvent se toucher.", "Placement case par case avec le bouton Tourner, ou placement aléatoire ; une fois ta flotte verrouillée, elle ne bouge plus.", "Quand les deux flottes sont prêtes, le premier tireur est tiré au sort. Un tir par tour, même après un touché ; une case déjà visée est refusée.", "Un touché annonce le type de navire ; un coulé annonce son identité. Le premier à toucher les 17 cases adverses gagne. Les positions restantes ne sont jamais montrées."], "objective": "Placez votre flotte en secret et retrouvez celle de votre partenaire.", "privacy": "Ta flotte reste secrète : seul le résultat de chaque tir est annoncé, même après la partie.", "step_texts": {}}}]$n$::jsonb) as x(id text, rules jsonb, config jsonb)),
changed as (
  select s.* from src s join public.games g on g.id = s.id
  where not exists (select 1 from public.game_versions v where v.game_id = s.id and v.version = g.current_version
                    and v.rules = s.rules and v.config = s.config)),
ins as (
  insert into public.game_versions (game_id, version, rules, config, published_at)
  select c.id, coalesce((select max(version) from public.game_versions where game_id = c.id), 0) + 1, c.rules, c.config, now()
  from changed c returning game_id, version)
update public.games g set current_version = ins.version from ins where g.id = ins.game_id;

update public.games set implementation = 'playable', updated_at = now()
  where id in ($n$N2-076$n$, $n$N2-079$n$, $n$N2-083$n$, $n$nd-de-chanceux$n$, $n$N2-078$n$) and implementation <> 'playable' and current_version is not null;

insert into public.catalogue_imports (content_version, report)
values ($n$c14-lot2-1.0.0$n$, jsonb_build_object('partie', 'mini-jeux lot 2', 'jouables', 5));
